"""Build a private, standalone in-game comparison; screenshots stay outside the mod ZIP."""
from pathlib import Path
import base64,json,html,statistics
R=Path(__file__).resolve().parents[1];folder=R/'build/emerald-languages'
labels={'en':'English','de':'Deutsch','fr':'Français','it':'Italiano','es':'Español'}
scenes={'picker-page1':'Sprachwahl · Seite 1','picker-page2':'Sprachwahl · Seite 2','title':'Titelbild','center':'Pokémon-Center','mart':'Markt / Außenbeschriftung','dialogue':'Dialogtext','summary':'Pokémon-Bericht'}
shots={l:{s:'data:image/png;base64,'+base64.b64encode((folder/f'{l}-{s}.png').read_bytes()).decode() for s in scenes} for l in labels}
reports={l:json.loads((R/f'build/emerald-{l}-profile-report.json').read_text()) for l in ['fr','it','es']}
perf=[]
for p in sorted(folder.glob('*-perf-*.log')):
 for line in p.read_text().splitlines():
  if line.startswith('PERFORMANCE_JSON '):perf.append(json.loads(line[len('PERFORMANCE_JSON '):]))
rows=''
for l in labels:
 vals=[v for v in perf if v['language']==l]
 if vals:
  rows+=f'<tr><th>{labels[l]}</th><td>{len(vals)}</td><td>{statistics.median(v["modLoadSeconds"] for v in vals):.2f} s</td><td>{statistics.median(v["update"]["p50Ms"] for v in vals):.3f} ms</td><td>{statistics.median(v["draw"]["p50Ms"] for v in vals):.3f} ms</td><td>{all(v["cacheHit"] for v in vals) if l!="en" else "–"}</td></tr>'
coverage=''.join(f'<tr><th>{labels[l]}</th><td>{v["mapped"]:,} / {v["total"]:,}</td><td>{v["mapped"]/v["total"]*100:.2f}%</td><td>{len(v["missing"])}</td></tr>' for l,v in reports.items())
missing=''.join('<details><summary>'+labels[l]+' · verbliebene US-Textschlüssel</summary><pre>'+html.escape('\n'.join(v['missing']))+'</pre></details>' for l,v in reports.items())
body='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Uni-Language Ascendant · Emerald im Vergleich</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f4f1e5;color:#173a3a;font:16px/1.55 system-ui}main{max-width:1200px;margin:auto;padding:42px 24px}header{border-top:10px solid #db484a;padding:24px 0}h1{font-size:clamp(30px,5vw,54px);line-height:1.1;margin:12px 0}h2{margin-top:40px}small,.muted{color:#54706c}.badge{background:#164f49;color:#fff;padding:7px 14px;border-radius:30px;font-weight:700}.controls{display:flex;gap:16px;flex-wrap:wrap;padding:20px;background:#ffdf79;border:2px solid #173a3a;border-radius:14px}label{display:grid;gap:6px;flex:1}select{padding:10px;border-radius:8px;border:1px solid #173a3a;background:#fff;font:inherit}section.compare{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:24px}figure{margin:0;background:#173a3a;color:white;border-radius:12px;overflow:hidden}figcaption{padding:12px 16px;font-weight:700}img{width:100%;display:block;image-rendering:pixelated}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #bbc8bc;padding:12px}aside{padding:18px 24px;background:#e2e9dc;border-left:5px solid #217d68}details{margin:10px 0;padding:12px;background:#e5e8dc}pre{overflow:auto;font-size:12px}a{color:#08766f}@media(max-width:700px){section.compare{grid-template-columns:1fr}table{font-size:12px}th,td{padding:7px}}</style>
<main><header><span class="badge">UNI-LANGUAGE ASCENDANT · 1.4.1</span><h1>Eine Region.<br>Fünf Spielsprachen.</h1><p>Echte Aufnahmen aus dem unveränderten Recompiler mit separat geladener Sprachmod.<br>Emerald · EN / DE / FR / IT / ES · macOS, 16. Oktober 2026</p></header>
<div class="controls"><label>Szene<select id="scene">SCENE_OPTIONS</select></label><label>Links<select id="left">LANG_OPTIONS</select></label><label>Rechts<select id="right">LANG_OPTIONS</select></label></div>
<section class="compare"><figure><figcaption id="leftLabel"></figcaption><img id="leftImage" alt="Ingame-Vergleich links"></figure><figure><figcaption id="rightLabel"></figcaption><img id="rightImage" alt="Ingame-Vergleich rechts"></figure></section>
<p class="muted">Gleiche Kartenpositionen und gleicher Pokémon-Testzustand. Die Titelanimationen wurden zeitgesteuert aufgenommen; Animationsphasen können abweichen. Der Dialog wurde für den Vergleich außerhalb des Gebäudes geöffnet.</p>
<aside>Die Schilder sind ROM-Grafiken. Sie werden aus der gewählten Sprach-ROM gelesen. Eine Sprachfassung darf denselben Schriftzug wie Englisch verwenden; es wird keine frei erfundene Übersetzung auf das Gebäude gesetzt.</aside>
<h2>Was wurde geprüft?</h2><p>Erstimport und Cache-Neustart; Titel, Center, Markt, Dialog, Pokémon-Bericht und Speichern. Namen und Fähigkeit von Bisasam wurden pro Sprache geprüft. Die Namenseingabe verwendet in IT/ES acht, in FR/DE neun Spalten. Sonderzeichen, Steuerzeichen, ROM-Prüfsummen, Sprachwahl, Zurück/Reset und Intro-Lebenszyklus sind durch zusätzliche Prüfungen abgedeckt.</p>
<h2>Abdeckung mit klaren Grenzen</h2><table><tr><th>Sprache</th><th>Zugeordnete Schlüssel</th><th>Anteil</th><th>US-Fallbacks</th></tr>COVERAGE</table>
<p>Die Zahlen zählen Registry-Schlüssel einschließlich Alias-Einträgen. Sie sind kein Prozentsatz des gesamten Spielverlaufs. Die zuvor fehlenden 42/54/49 Schlüssel sind in 1.4.1 ergänzt, zusätzlich sind vertauschte Dialoge korrigiert. Die zwei verbliebenen Schlüssel sind englische Abspann-Namen; die Listen stehen unten. 74 japanische Resttext-Schlüssel in den europäischen Daten sind kein unterstützter japanischer Zeichensatz. Kein vollständiger Durchspieltest, keine Prüfung jedes Kampfes oder jeder Link-Funktion und kein unabhängiger vollständiger Importvergleich für FR/IT/ES.</p>MISSING
<h2>Cache und Laufzeit</h2><table><tr><th>Sprache</th><th>Läufe</th><th>Mod-Start, Median</th><th>Update p50</th><th>Draw p50</th><th>Cache-Treffer</th></tr>PERF</table>
<p>Messreihe aus 1.4.0, unveränderte Laufzeitlogik in 1.4.1. Je Lauf 360 Frames in Wurzelheim-Nachbarstadt Oldale Town, gleiche Position. Die Tabelle zeigt den Median der jeweiligen Laufwerte. Reihenfolge: EN, FR, IT, ES, DE, ES, IT, FR, EN. Gleichzeitig laufende andere Aufgaben belasten den Rechner: Diese Messung prüft die Funktion und Größenordnung, nicht die statistische Gleichheit der Performance. Der Cache verhindert erneutes ROM-Kompilieren, hat aber weiterhin Lade- und Integritätsprüfkosten. Der beobachtete Lua-Heap lag ohne erzwungene Speicherbereinigung bei etwa 96 MiB für EN und 196–202 MiB mit Sprachdaten. Das ist eine Momentaufnahme einschließlich noch nicht eingesammelter Objekte, kein Nachweis des dauerhaft belegten Speichers. Die Mod ergänzt während des Spiels keine Übersetzung pro Frame; der Grafik-Leseadapter bleibt aktiv.</p>
<h2>Benötigte Dateien</h2><p>US Emerald 1.0 plus die gewünschte Sprach-ROM, jeweils Revision 0. Die vollständigen SHA-1-Werte werden vor dem Titelbild und in der mitgelieferten ROM-Liste angezeigt. Die drei bereitgestellten FR/IT/ES-ROMs passen. Japanisch/Koreanisch und FR/IT/ES anderer Editionen sind noch nicht freigegeben.</p><p>Diese private Doku enthält nur Screenshots aus den lokalen Tests. Das verteilbare Mod-ZIP enthält keine ROMs oder extrahierten Spielinhalte.</p></main>
<script>const shots=SHOTS,labels=LABELS,scenes=SCENES;const scene=document.querySelector('#scene'),left=document.querySelector('#left'),right=document.querySelector('#right');right.value='de';scene.value='mart';function draw(){for(const side of ['left','right']){const l=document.querySelector('#'+side).value;document.querySelector('#'+side+'Image').src=shots[l][scene.value];document.querySelector('#'+side+'Label').textContent=labels[l]+' · '+scenes[scene.value]}}for(const el of [scene,left,right])el.addEventListener('change',draw);draw();</script></html>'''
for a,b in {'SCENE_OPTIONS':''.join(f'<option value="{k}">{v}</option>' for k,v in scenes.items()),'LANG_OPTIONS':''.join(f'<option value="{k}">{v}</option>' for k,v in labels.items()),'COVERAGE':coverage,'MISSING':missing,'PERF':rows,'SHOTS':json.dumps(shots),'LABELS':json.dumps(labels),'SCENES':json.dumps(scenes)}.items():body=body.replace(a,b)
# The focused correction captures intentionally show different dialogue examples.
fixed='<h2>Textkorrekturen in 1.4.1</h2><p>Zusätzlich zur Abdeckung wurden vertauschte Dialogverweise korrigiert. Alle 176 neu hinzugefügten oder geänderten Schlüssel wurden beim Erstimport und aus dem Cache mit den Original-ROM-Textdaten verglichen. Diese Aufnahmen zeigen gezielt drei reparierte Dialoge im Renderer; kein Nachspielen der vollständigen Ereigniskette.</p><section class="compare">'
for lang in ['fr','it','es']:
 raw=(folder/f'{lang}-fixed-dialogue.png').read_bytes()
 fixed+='<figure><figcaption>'+labels[lang]+'</figcaption><img alt="Korrigierter Dialog '+labels[lang]+'" src="data:image/png;base64,'+base64.b64encode(raw).decode()+'"></figure>'
fixed+='</section>'
body=body.replace('<h2>Abdeckung mit klaren Grenzen</h2>',fixed+'<h2>Abdeckung mit klaren Grenzen</h2>')
out=R/'dist/Uni-Language-Ascendant-Ingame.html';out.write_text(body)
(folder/'performance-results.json').write_text(json.dumps(perf,indent=2)+'\n')
print(out,len(body),'bytes',len(perf),'performance runs')

# Keep the shipped performance notes in sync without bundling screenshots.
p=R/'mod/Performance.html';old=p.read_text();start='<!-- EMERALD_1_4 -->';end='<!-- /EMERALD_1_4 -->'
if start in old:old=old[:old.index(start)]+old[old.index(end)+len(end):]
section=start+'<h2>Emerald 1.4.0 · fünf Sprachen</h2><p>16.10.2026 · neun Läufe, je 360 Frames, EN/FR/IT/ES/DE/ES/IT/FR/EN. Alle Sprachläufe treffen den bestehenden Cache. FR/IT/ES-Erstverarbeitung: rund 12 Sekunden unter gleichzeitiger Rechnerlast.</p><table><tr><th>Sprache</th><th>Läufe</th><th>Warmer Mod-Start</th><th>Update p50</th><th>Draw p50</th><th>Cache</th></tr>'+rows+'</table><p>Median der Laufwerte. Zusätzliche Start- und Speicherkosten bestehen weiterhin: Lua-Heap-Momentaufnahme etwa 96 MiB EN gegenüber 196–202 MiB mit Sprachdaten, ohne erzwungene GC. Draw enthält Treiber-/VSync-Wartezeiten. Andere Aufgaben liefen parallel; aus dieser kleinen Stichprobe lässt sich keine belastbare prozentuale Verlangsamung oder Gleichheit ableiten. Kein vollständiger Spiel- oder Kampfbenchmark.</p><h2>Frühere Messreihe · 1.3.0</h2>'+end
old=old.replace('<h1>Performance-Prüfung</h1>','<h1>Performance-Prüfung</h1>'+section).replace('Ascendant 1.3</title>','Ascendant 1.4</title>');p.write_text(old)
